const data = msg.payload;
const values = data.value;
const geos = data.dimension.geo.category.index;
const times = data.dimension.time.category.index;

const geoKeys = Object.keys(geos).sort((a,b) => geos[a] - geos[b]);
const timeKeys = Object.keys(times).sort((a,b) => times[a] - times[b]);

let rows = [];
geoKeys.forEach(geo => {
    timeKeys.forEach(time => {
        const idx = geos[geo] * timeKeys.length + times[time];
        const val = values[idx];
        if (val !== null && val !== undefined) {
            rows.push([geo, parseInt(time), val]);
        }
    });
});

const valuePlaceholders = rows.map((_, i) => 
    `($${i*3+1}, $${i*3+2}, $${i*3+3})`
).join(',');

msg.query = `
    INSERT INTO net_earnings (country_code, year, annual_net_eur)
    VALUES ${valuePlaceholders}
    ON CONFLICT (country_code, year) 
    DO UPDATE SET annual_net_eur = EXCLUDED.annual_net_eur
`;
msg.params = rows.flat();
return msg;

return new Promise((resolve, reject) => {
    const url = 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/earn_nt_net?format=JSON&lang=EN&geo=PT&geo=DE&geo=FR&geo=ES&geo=IT&geo=NL&geo=PL&sinceTimePeriod=2021';

    https.get(url, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
            msg.payload = JSON.parse(data);
            resolve(msg);
        });
    }).on('error', (err) => {
        node.error(err.message);
        reject(err);
    });
});
